import React, { useEffect, useState, useMemo, useCallback, useRef } from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";
import "./Shop.css";

const API_BASE_URL = "http://localhost:5009";
const SEARCH_DEBOUNCE_MS = 300;

/** Pull a usable user id out of a decoded JWT, whatever shape it comes in. */
function extractUserId(decoded) {
  const raw = decoded?.userId || decoded?.id || decoded?._id || decoded?.sub || "";
  return String(raw).trim() || null;
}

function useDebouncedValue(value, delayMs) {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(timer);
  }, [value, delayMs]);

  return debounced;
}

function Shop({ onBuy, purchasedItems = {} }) {
  const [items, setItems] = useState([]);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const debouncedSearchTerm = useDebouncedValue(searchTerm, SEARCH_DEBOUNCE_MS);
  const [reloadKey, setReloadKey] = useState(0);

  // Decode current user once on mount.
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    try {
      const decoded = jwtDecode(token);
      setCurrentUserId(extractUserId(decoded));
    } catch (err) {
      setCurrentUserId(null);
    }
  }, []);

  // Fetch books; cancellable so we don't setState after unmount, retryable via reloadKey.
  useEffect(() => {
    const controller = new AbortController();

    setLoading(true);
    setError(null);

    fetch(`${API_BASE_URL}/books`, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`Request failed with status ${res.status}`);
        return res.json();
      })
      .then((data) => setItems(Array.isArray(data) ? data : []))
      .catch((err) => {
        if (err.name !== "AbortError") setError("Couldn't load books. Please try again.");
      })
      .finally(() => setLoading(false));

    return () => controller.abort();
  }, [reloadKey]);

  const filteredItems = useMemo(() => {
    if (!items.length) return [];

    const currentId = String(currentUserId || "").trim();
    const search = debouncedSearchTerm.toLowerCase().trim();

    return items.filter((item) => {
      if (!item) return false;

      const sellerId = String(item.sellerId?._id || "").trim();
      const isNotMine = !currentId || sellerId !== currentId;

      const title = (item.title || "").toLowerCase().trim();
      const matchesSearch = search === "" || title.includes(search);

      return isNotMine && matchesSearch;
    });
  }, [items, currentUserId, debouncedSearchTerm]);

  const handleRetry = useCallback(() => setReloadKey((k) => k + 1), []);

  return (
    <>
      <Navbar />

      <div className="Body">
        <div className="shop-search-wrap">
          <div className="shop-search">
            <input
              type="text"
              placeholder="Search for books..."
              aria-label="Search for books"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="shop-search-input"
            />

            {searchTerm && (
              <button
                onClick={() => setSearchTerm("")}
                aria-label="Clear search"
                className="shop-search-clear"
              >
                ×
              </button>
            )}
          </div>
        </div>

        <div className="shop-grid">
          {loading ? (
            <div className="HeadMo">
              <h1>Loading books…</h1>
            </div>
          ) : error ? (
            <div className="HeadMo">
              <h1>{error}</h1>
              <button className="shop-retry-btn" onClick={handleRetry}>
                Retry
              </button>
            </div>
          ) : filteredItems.length === 0 ? (
            <div className="HeadMo">
              <h1>
                {searchTerm
                  ? `No Books found matching "${searchTerm}"`
                  : "No Books!"}
              </h1>
            </div>
          ) : (
            filteredItems.map((item) => {
              const itemId = String(item._id || item.id);
              const isPurchased = !!purchasedItems[itemId];

              return (
                <Card key={itemId} {...item}>
                  <button
                    onClick={() => !isPurchased && onBuy(item)}
                    disabled={isPurchased}
                    aria-label={isPurchased ? "Already added to cart" : `Add ${item.title || "item"} to cart`}
                    className={`shop-buy-btn ${isPurchased ? "shop-buy-btn--disabled" : ""}`}
                  >
                    {isPurchased ? "Added to Cart" : "Add to Cart"}
                  </button>
                </Card>
              );
            })
          )}
        </div>
      </div>

      <Footer />
    </>
  );
}

export default Shop;
